const body = $input.first().json.body || $input.first().json;
const message = body.message || body.channel_post || {};
const from = message.from || {};
const chat = message.chat || {};

if (!message.text && !message.voice) {
  return [{ json: { ignore: true, reason: 'No text or voice message' } }];
}

return [{
  json: {
    ignore: false,
    telegram_id: String(from.id || chat.id),
    chat_id: String(chat.id),
    first_name: from.first_name || '',
    last_name: from.last_name || '',
    username: from.username || '',
    text: (message.text || '').trim(),
    message_id: message.message_id,
    date: message.date,
    is_voice: !!message.voice
  }
}];

const snapshot = $input.first().json;
const lead = snapshot.lead;
const qual = snapshot.qualification || {};
const raw = qual.raw_answers || {};
const chatData = $('Normalizar Payload Telegram').first().json;
const userText = chatData.text || '';
const state = lead.current_state;
const name = lead.first_name || 'hola';

const isAgente1 = ['NEW_LEAD', 'QUALIFYING', 'WARM', 'PARTIAL'].includes(state);

// Mapeo estricto y secuencial de turnos de calificación
let currentAnswerFor = 'P1';
let nextQuestionGuide = 'Para partir: ¿qué necesitas trabajar en este momento (marca desde cero, rebranding, identidad visual, arquitectura de marca, brand book, naming, o marca + espacio físico)?';

const isFirstContact = (state === 'NEW_LEAD' && Object.keys(raw).length === 0);

if (isFirstContact) {
  currentAnswerFor = 'GREETING';
  nextQuestionGuide = 'Para partir: ¿qué necesitas trabajar en este momento — marca desde cero, rebranding, identidad visual, arquitectura de marca, brand book, naming, o marca + espacio físico?';
} else if (!raw.P1) {
  currentAnswerFor = 'P1';
  nextQuestionGuide = 'Cuéntame un poco de tu negocio — a qué se dedican y cuál es el problema principal que te gustaría resolver con este proyecto.';
} else if (!raw.P2) {
  currentAnswerFor = 'P2';
  nextQuestionGuide = '¿Quién toma la decisión final sobre este proyecto — tú, tú con socios, o alguien más tiene que aprobarlo?';
} else if (!raw.P3_AUTHORITY) {
  currentAnswerFor = 'P3_AUTHORITY';
  nextQuestionGuide = 'Para orientarte bien: nuestros proyectos de marca parten desde $1.200.000 CLP. ¿Ese rango te hace sentido para lo que estás pensando?';
} else if (!raw.P3_INVESTMENT) {
  currentAnswerFor = 'P3_INVESTMENT';
  nextQuestionGuide = 'Si vemos que hay buen encaje, ¿podrías coordinar una videollamada con el equipo — esta semana, en las próximas dos, o prefieres info y precios primero?';
} else if (!raw.P4) {
  currentAnswerFor = 'P4';
  nextQuestionGuide = 'Resume lo conversado brevemente y felicítalo porque encaja excelente con el estudio. Infórmale que lo pasas con el equipo de coordinación para la videollamada.';
}

const systemPrompt = `Eres el asistente conversacional del equipo de Fernández Briceño Studio (FBS), un estudio de branding estratégico y diseño en Chile.\nConversas de forma humana, cercana, ágil y profesional por Telegram con ${name}.\n\nDIRECTIVAS INVIOLABLES:\n1. Tono: Tuteo latino/chileno natural y profesional. Mensajes CORTOS (máximo 2 a 3 líneas). Cero párrafos largos.\n2. Cero lenguaje robótico: PROHIBIDO decir "procesando", "gracias por responder", "consulta registrada", etc.\n3. Si es el primer mensaje o saludo del prospecto (${isFirstContact ? 'SÍ ES PRIMER CONTACTO' : 'NO'}), dale una bienvenida cálida presentándote como parte del equipo de FBS.\n4. Si el prospecto acaba de contarte algo, haz siempre una micro-reacción corta y empática (ej: "Ya, tiene sentido.", "Perfecto, eso ayuda a entender el panorama.", "Ok, anotado.", "Entiendo — pasa más de lo que crees.", "Buena info, gracias.") antes de formular la siguiente pregunta.\n5. Si el usuario pregunta cómo lo van a contactar o por qué no se le piden datos: Explícale con total naturalidad que la videollamada se agenda directamente por link (Cal.com), donde él mismo elige día y hora e ingresa su correo para la invitación de Google Meet.\n6. Si pregunta si eres bot: "Soy un asistente del equipo — te ayudo a agilizar esto antes de pasarte con una persona real."\n\nTURNO ACTUAL:\n- Nombre: ${name}\n- Pregunta que el prospecto acaba de responder: ${currentAnswerFor}\n- Mensaje que envió el prospecto: "${userText}"\n- Pregunta que debes formular OBLIGATORIAMENTE a continuación: "${nextQuestionGuide}"\n\nResponde OBLIGATORIAMENTE en JSON:\n{\n  "parsed_answer": "Texto limpio de la respuesta del prospecto a ${currentAnswerFor}",\n  "bot_reply": "Tu mensaje exacto en español para Telegram (micro-reacción empática + ${nextQuestionGuide})"\n}`;

const calLink = `https://cal.com/fbs-studio/consulta-30min?lead_id=${lead.id}`;
const formLink = `https://fbs.studio/precall/${lead.id}`;
const service = qual.service_needed || 'tu proyecto de marca';

let agente2Reply = '';
if (state === 'QUALIFIED') {
  agente2Reply = `¡Hola, ${name}! Soy parte del equipo de coordinación de FBS. Vi que conversaste con el equipo sobre ${service} y el encaje es excelente. Vamos a coordinar la videollamada estratégica de 30 min (sin costo): puedes elegir el día y hora que mejor te acomode en este link: ${calLink}`;
} else if (state === 'CONSULTATION_PENDING') {
  agente2Reply = `Tu cita ya está en agenda. Por favor completa este breve formulario de 5 minutos antes de la reunión para enfocar la llamada directamente en estrategia: ${formLink}`;
} else {
  agente2Reply = `Gracias por tu mensaje, ${name}. El equipo ya tiene tu caso registrado y te responderemos a la brevedad.`;
}

return [{
  json: {
    is_agente_1: isAgente1,
    lead_id: lead.id,
    chat_id: chatData.chat_id,
    current_answer_for: currentAnswerFor,
    user_answer: userText,
    system_prompt: systemPrompt,
    agente2_reply: agente2Reply
  }
}];

let rawText = '';
const geminiOut = $input.first()?.json || {};

if (geminiOut.content?.parts?.[0]?.text) {
  rawText = geminiOut.content.parts[0].text;
} else if (typeof geminiOut === 'string') {
  rawText = geminiOut;
} else if (geminiOut.bot_reply) {
  return [{ json: geminiOut }];
}

let parsed = {};
try {
  const clean = rawText.replace(/```(?:json)?\s*([\s\S]*?)\s*```/i, '$1').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { parsed_answer: $('Preparar Enrutamiento y Prompt').first().json.user_answer, bot_reply: rawText };
}

const routeData = $('Preparar Enrutamiento y Prompt').first().json;

return [{
  json: {
    lead_id: routeData.lead_id,
    chat_id: routeData.chat_id,
    current_answer_for: routeData.current_answer_for,
    parsed_answer: parsed.parsed_answer || routeData.user_answer,
    bot_reply: parsed.bot_reply || rawText
  }
}];

const geminiData = $('Procesar Salida de Gemini').first()?.json || {};
const apiData = $input.first()?.json || {};
const routeData = $('Preparar Enrutamiento y Prompt').first()?.json || {};

const finalReply = geminiData.bot_reply || apiData.message_text || '¡Hola! Qué gusto saludarte. Soy del equipo de FBS. ¿Qué necesitan trabajar hoy para su marca?';

return [{
  json: {
    chat_id: geminiData.chat_id || routeData.chat_id,
    reply_text: finalReply,
    lead_id: geminiData.lead_id || routeData.lead_id
  }
}];

const item = $input.first().json;
return [{
  json: {
    chat_id: item.chat_id,
    reply_text: item.agente2_reply,
    lead_id: item.lead_id
  }
}];
